package org.apache.commons.lang3.text.translate;

import junit.framework.TestCase;
import java.nio.CharBuffer;
import java.util.HashMap;
import java.util.Map;

public class LookupTranslatorBugOriginTest extends TestCase {

    public void testLookupTranslatorWithCharBuffer() {
        Map<CharSequence, CharSequence> lookupMap = new HashMap<CharSequence, CharSequence>();
        lookupMap.put("<", "&lt;");

        LookupTranslator translator = new LookupTranslator(lookupMap);

        CharSequence input = CharBuffer.wrap("1 < 2".toCharArray());
        java.io.StringWriter writer = new java.io.StringWriter();

        try {
            int result = translator.translate(input, 2, writer);
            // result should be the number of characters consumed from the input.
            // If it translated "<", it should return 1.
            // If it failed to translate, it returns 0.
            assertTrue("LookupTranslator should have translated the CharBuffer input", result > 0);
            assertEquals("&lt;", writer.toString());
        } catch (java.io.IOException e) {
            fail("IOException should not have been thrown");
        }
    }
}

