package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringUtilsBugOriginTest extends TestCase {

    /**
     * A simple CharSequence implementation that does not override equals(Object).
     */
    private static class TestCharSequence implements CharSequence {
        private final String str;

        public TestCharSequence(String str) {
            this.str = str;
        }

        public int length() {
            return str.length();
        }

        public char charAt(int index) {
            return str.charAt(index);
        }

        public CharSequence subSequence(int start, int end) {
            return str.subSequence(start, end);
        }

        public String toString() {
            return str;
        }

        // Note: equals(Object) is NOT overridden.
    }

    public void testEqualsWithDifferentCharSequenceImplementations() {
        CharSequence cs1 = new TestCharSequence("abc");
        CharSequence cs2 = new StringBuilder("abc");

        // According to the bug report, StringUtils.equals(CharSequence, CharSequence)
        // should return true if the sequences are identical, even if the classes
        // are different and do not implement equals(Object) to recognize each other.
        // The bug is that it returns false because it relies on cs1.equals(cs2).

        assertTrue("StringUtils.equals(CharSequence, CharSequence) should return true for identical sequences",
                StringUtils.equals(cs1, cs2));
    }
}

package org.apache.commons.lang3.time;

import java.util.Calendar;
import junit.framework.TestCase;

public class DateUtilsBugOriginTest extends TestCase {

    public void testIsSameLocalTime() {
        Calendar a = Calendar.getInstance();
        a.setTimeInMillis(1297364400000L);

        Calendar b = Calendar.getInstance();
        b.setTimeInMillis(1297321200000L);

        // The reporter says this should be false, but it returns true because of the bug.
        // 1297364400000L is 2011-02-10 19:00:00 UTC (approx)
        // 1297321200000L is 2011-02-10 07:00:00 UTC (approx)
        // Both have HOUR=7, but different HOUR_OF_DAY (7 vs 19).
        assertFalse("DateUtils.isSameLocalTime(a, b) should be false", DateUtils.isSameLocalTime(a, b));
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringUtilsBugOriginTest extends TestCase {

    private static final String CharU20000 = "\uD840\uDC00";
    private static final String CharU20001 = "\uD840\uDC01";

    public void testContainsAnyWithSupplementaryCharacters() {
        // The reporter states that StringUtils.containsAny incorrectly matches these characters.
        // CharU20000 and CharU20001 are different supplementary characters.
        // They share the same high surrogate (\uD840) but have different low surrogates (\uDC00 vs \uDC01).
        // If the implementation incorrectly iterates over chars instead of code points, 
        // it might match the high surrogate.

        assertFalse("StringUtils.containsAny(CharU20000, CharU20001) should be false", 
                    StringUtils.containsAny(CharU20000, CharU20001));
        assertFalse("StringUtils.containsAny(CharU20001, CharU20000) should be false", 
                    StringUtils.containsAny(CharU20001, CharU20000));
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;
import java.util.Locale;

public class StringUtilsBugOriginTest extends TestCase {

    public void testContainsIgnoreCase_LocaleIndependence() {
        Locale defaultLocale = Locale.getDefault();
        try {
            // The Turkish i/I problem is the classic example of locale-sensitive case conversion.
            // In Turkish, 'i'.toUpperCase() is '\u0130' (capital I with dot)
            // and 'I'.toLowerCase() is '\u0131' (lowercase dotless i).
            Locale.setDefault(new Locale("tr", "TR"));

            String str = "i";
            String searchStr = "I";

            // StringUtils.containsIgnoreCase should behave like String.equalsIgnoreCase
            // which is locale-independent (it uses Character.toLowerCase/toUpperCase which 
            // are not locale-aware in the way String.toLowerCase(Locale) is).
            // If StringUtils.containsIgnoreCase uses String.toLowerCase() internally, 
            // it will fail for "i" and "I" in Turkish locale.

            assertTrue("StringUtils.containsIgnoreCase(\"i\", \"I\") should be true even in Turkish locale",
                    StringUtils.containsIgnoreCase(str, searchStr));
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }
}

