package org.apache.commons.lang3.math;

import junit.framework.TestCase;

public class FractionBugOriginTest extends TestCase {
    public void testReduceZeroNumerator() {
        Fraction f = Fraction.getFraction(0, 1);
        // The report says Fraction.reduce() enters an infinite loop when numerator == 0.
        // We call it and expect it to return (or not hang).
        // A common expectation for 0/n reduced is 0/1.
        Fraction reduced = f.reduce();
        assertEquals(0, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }
}

