package org.apache.commons.lang3.time;

import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import junit.framework.TestCase;

public class DateUtilsBugOriginTest extends TestCase {

    public void testRoundLang346() {
        TimeZone gmt = TimeZone.getTimeZone("GMT");
        Calendar testCalendar = Calendar.getInstance(gmt);
        testCalendar.set(2007, 6, 2, 8, 9, 50);
        testCalendar.set(Calendar.MILLISECOND, 0);
        Date date = testCalendar.getTime();

        Date rounded = DateUtils.round(date, Calendar.MINUTE);

        Calendar expectedCalendar = Calendar.getInstance(gmt);
        expectedCalendar.set(2007, 6, 2, 8, 10, 0);
        expectedCalendar.set(Calendar.MILLISECOND, 0);
        Date expected = expectedCalendar.getTime();

        assertEquals("After round() Mon Jul 02 08:09:50 GMT 2007 should be Mon Jul 02 08:10:00 GMT 2007", 
                     expected, rounded);
    }
}

