package org.apache.commons.lang3.text;

import junit.framework.TestCase;

public class StrBuilderBugOriginTest extends TestCase {

    public void testLang295() {
        StrBuilder sb = new StrBuilder(10);
        sb.append("abc");

        // The bug report mentions that thisBuf.length is used instead of size.
        // In StrBuilder, thisBuf.length is the capacity, while size is the actual length.
        // One place where thisBuf.length was used incorrectly is in delete(int, int).
        // If we delete everything, the internal buffer length (capacity) should not be used to determine the end index if it exceeds size.

        // Test delete(int, int) with an end index that is greater than size but less than capacity.
        // If it uses thisBuf.length, it might not throw an exception or might behave incorrectly.
        // However, the report says it uses thisBuf.length when it should use size.

        // Let's try to reproduce the issue where delete or similar methods might be affected.
        // Based on the fix in LANG-295, the methods affected were delete(int, int) and setLength(int).

        StrBuilder sb2 = new StrBuilder(10);
        sb2.append("abc");
        try {
            sb2.delete(2, 5);
            // If size is 3, deleting from 2 to 5 should be equivalent to deleting from 2 to 3.
            // If it uses thisBuf.length (10), it might try to delete up to index 5.
            assertEquals("ab", sb2.toString());
        } catch (IndexOutOfBoundsException e) {
            // Should not throw if it correctly handles end > size
        }

        // Another case: insert(int, String) or similar.
        // The report mentions two places. Let's check the source of StrBuilder at that time.
        // The two places were in deleteImpl and validateIndex.
    }

    public void testDeleteImplWithLargeEnd() {
        StrBuilder sb = new StrBuilder(10); // capacity 10
        sb.append("abc"); // size 3

        // If delete(int, int) uses thisBuf.length instead of size to cap the end index:
        // sb.delete(1, 5) should result in "a" because it should be capped at size 3.
        sb.delete(1, 5);
        assertEquals("a", sb.toString());
        assertEquals(1, sb.length());
    }

    public void testSetLength() {
        StrBuilder sb = new StrBuilder(10);
        sb.append("abc");
        // If setLength uses thisBuf.length incorrectly
        sb.setLength(2);
        assertEquals(2, sb.length());
        assertEquals("ab", sb.toString());
    }
}

