package org.apache.commons.lang3.time;

import java.util.Calendar;
import java.util.TimeZone;
import junit.framework.TestCase;

public class DurationFormatUtilsBugOriginTest extends TestCase {
    public void testLANG815() {
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone( "UTC" ));
        calendar.set(2012, Calendar.JUNE, 30, 0, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        long startMillis = calendar.getTimeInMillis();

        calendar.set(2012, Calendar.AUGUST, 8, 0, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        long endMillis = calendar.getTimeInMillis();

        // The reporter says:
        // "Duration must be 1 month and 9 days (June 30 + 1 month = July 30, July 30 + 9 Days = August 8)
        // but current logic tells this duration is 1 month and 8 days."
        // We assert that it is NOT "1 8" to reproduce the failure if the bug is present.
        String result = DurationFormatUtils.formatPeriod(startMillis, endMillis, "M d");
        assertFalse("Should not be 1 month and 8 days", "1 8".equals(result));
    }
}

package org.apache.commons.lang3.builder;

import junit.framework.TestCase;

public class HashCodeBuilderBugOriginTest extends TestCase {

    public void testReflectionHashCodeWithArrays() {
        int hash1 = HashCodeBuilder.reflectionHashCode(new double[] {1.0, 1.0});
        int hash2 = HashCodeBuilder.reflectionHashCode(new double[] {2.0, 2.0});
        int hash3 = HashCodeBuilder.reflectionHashCode(new int[] {3, 3});
        int hash4 = HashCodeBuilder.reflectionHashCode(new int[] {4, 4});

        // The reporter states that for any array, the result is always 17.
        // We assert that different arrays should ideally not produce the same constant 17,
        // or at least that they shouldn't all be identical if they have different content.
        // Based on the report, the "wrong" behavior is that they all return 17.

        assertFalse("HashCodeBuilder.reflectionHashCode should not return 17 for all arrays", 
            hash1 == 17 && hash2 == 17 && hash3 == 17 && hash4 == 17);
    }
}

