package org.apache.commons.lang3.text.translate;

import junit.framework.TestCase;
import java.nio.CharBuffer;
import java.util.HashMap;
import java.util.Map;

public class LookupTranslatorBugOriginTest extends TestCase {
    public void testLang882() throws java.io.IOException {
        final Map<CharSequence, CharSequence> lookupMap = new HashMap<CharSequence, CharSequence>();
        lookupMap.put("<", "&lt;");

        final LookupTranslator lt = new LookupTranslator(lookupMap);
        final CharSequence cs2 = CharBuffer.wrap("1 < 2".toCharArray());

        final java.io.StringWriter out = new java.io.StringWriter();
        final int result = lt.translate(cs2, 2, out);

        // If the bug is present, translate returns 0 because it fails to find "<" in the map
        // when the input is a CharBuffer (or subSequence thereof).
        // The reporter says it should work identically to String.
        assertTrue("Should have translated the character", result > 0);
        assertEquals("Should have translated < to &lt;", "&lt;", out.toString());
    }
}

